package com.pipepatrol;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Component;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import java.security.*;
import java.sql.*;
import java.nio.file.*;
import java.util.*;
@Component public class PatrolDatabase {
 final ObjectMapper json; String url;
 final List<String> tables=List.of("network_nodes","network_pipes","patrol_tasks","patrol_alerts","patrol_devices","patrol_messages","task_events");
 public PatrolDatabase(ObjectMapper j){json=j;}
 void open(String legacy) throws Exception {
  Path path=Path.of(legacy).toAbsolutePath();Files.createDirectories(path.getParent());
  url="jdbc:h2:file:"+path.toString().replace('\\','/')+".database;DB_CLOSE_ON_EXIT=FALSE";
  try(Connection c=connect();Statement s=c.createStatement()){
   for(String t:tables)s.execute("CREATE TABLE IF NOT EXISTS "+t+" (id VARCHAR(100) PRIMARY KEY, payload CLOB NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
   s.execute("CREATE TABLE IF NOT EXISTS accounts(username VARCHAR(40) PRIMARY KEY,display_name VARCHAR(80),role VARCHAR(20),enabled BOOLEAN,phone VARCHAR(40),area VARCHAR(100),password_hash VARCHAR(500))");
   s.execute("CREATE TABLE IF NOT EXISTS network_meta(id INT PRIMARY KEY, source VARCHAR(500), sample BOOLEAN)");
   s.execute("CREATE TABLE IF NOT EXISTS telemetry_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, device VARCHAR(60), task VARCHAR(100), battery DOUBLE PRECISION,distance DOUBLE PRECISION,temperature DOUBLE PRECISION,recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
  }
 }
 Connection connect() throws SQLException{return DriverManager.getConnection(url,"sa","");}
 boolean hasState() throws Exception {try(Connection c=connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM network_meta")){r.next();return r.getInt(1)>0;}}
 <T> List<T> read(String table,Class<T> type) throws Exception {List<T> out=new ArrayList<>();try(Connection c=connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT payload FROM "+table+" ORDER BY id")){while(r.next())out.add(json.readValue(r.getString(1),type));}return out;}
 PatrolController.State load() throws Exception {
  var s=new PatrolController.State();s.nodes=read("network_nodes",PatrolController.Node.class);s.pipes=read("network_pipes",PatrolController.Pipe.class);s.tasks=read("patrol_tasks",PatrolController.Task.class);s.alerts=read("patrol_alerts",PatrolController.Alert.class);s.devices=read("patrol_devices",PatrolController.Device.class);s.messages=read("patrol_messages",PatrolController.Message.class);s.events=read("task_events",PatrolController.Event.class);
  try(Connection c=connect();Statement st=c.createStatement();ResultSet r=st.executeQuery("SELECT source,sample FROM network_meta WHERE id=1")){if(r.next()){s.networkSource=r.getString(1);s.demo=r.getBoolean(2);}}return s;
 }
 void write(Connection c,String table,List<?> rows)throws Exception{
  try(Statement s=c.createStatement()){s.executeUpdate("DELETE FROM "+table);}
  try(PreparedStatement p=c.prepareStatement("INSERT INTO "+table+"(id,payload) VALUES(?,?)")){for(Object row:rows){var tree=json.valueToTree(row);p.setString(1,tree.get("id").asText());p.setString(2,json.writeValueAsString(row));p.addBatch();}p.executeBatch();}
 }
 synchronized void save(PatrolController.State s){try(Connection c=connect()){c.setAutoCommit(false);try{write(c,"network_nodes",s.nodes);write(c,"network_pipes",s.pipes);write(c,"patrol_tasks",s.tasks);write(c,"patrol_alerts",s.alerts);write(c,"patrol_devices",s.devices);write(c,"patrol_messages",s.messages);write(c,"task_events",s.events);try(PreparedStatement p=c.prepareStatement("MERGE INTO network_meta(id,source,sample) KEY(id) VALUES(1,?,?)")){p.setString(1,s.networkSource);p.setBoolean(2,s.demo);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}catch(Exception e){throw new IllegalStateException("数据库保存失败",e);}}
 static String hash(String password){try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);byte[] h=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(password.toCharArray(),salt,120000,256)).getEncoded();return Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(h);}catch(Exception e){throw new IllegalStateException(e);}}
 static boolean verify(String password,String stored){try{String[] p=stored.split(":");byte[] h=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(password.toCharArray(),Base64.getDecoder().decode(p[0]),120000,256)).getEncoded();return MessageDigest.isEqual(h,Base64.getDecoder().decode(p[1]));}catch(Exception e){return false;}}
 record Account(String username,String displayName,String role,boolean enabled,String phone,String area){}
 List<Account> accounts(){try(Connection c=connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM accounts ORDER BY role,username")){List<Account>a=new ArrayList<>();while(r.next())a.add(new Account(r.getString("username"),r.getString("display_name"),r.getString("role"),r.getBoolean("enabled"),r.getString("phone"),r.getString("area")));return a;}catch(Exception e){throw new IllegalStateException(e);}}
 void account(String name,String display,String password,boolean enabled,String phone,String area,boolean create){try(Connection c=connect()){
  String sql=create?"INSERT INTO accounts(username,display_name,password_hash,role,enabled,phone,area) VALUES(?,?,?,'worker',?,?,?)":"UPDATE accounts SET display_name=?,enabled=?,phone=?,area=? WHERE username=?";
  try(PreparedStatement p=c.prepareStatement(sql)){if(create){p.setString(1,name);p.setString(2,display);p.setString(3,hash(password));p.setBoolean(4,enabled);p.setString(5,phone);p.setString(6,area);}else{p.setString(1,display);p.setBoolean(2,enabled);p.setString(3,phone);p.setString(4,area);p.setString(5,name);}p.executeUpdate();}
  if(!create&&password!=null&&!password.isBlank())try(PreparedStatement p=c.prepareStatement("UPDATE accounts SET password_hash=? WHERE username=?")){p.setString(1,hash(password));p.setString(2,name);p.executeUpdate();}
 }catch(Exception e){throw new IllegalArgumentException("账号保存失败，请检查账号是否已存在");}}
 void bootstrap(String admin,String worker)throws Exception {if(!accounts().isEmpty())return;account("admin","系统管理员",admin,true,"","管理中心",true);try(Connection c=connect();Statement s=c.createStatement()){s.executeUpdate("UPDATE accounts SET role='admin' WHERE username='admin'");}account("worker","作业人员一",worker,true,"","北区",true);account("worker02","作业人员二",worker,true,"","南区",true);account("worker03","作业人员三",worker,true,"","东区",true);}
 Account authenticate(String name,String password){try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT password_hash FROM accounts WHERE username=? AND enabled=TRUE")){p.setString(1,name);try(ResultSet r=p.executeQuery()){if(r.next()&&verify(password,r.getString(1)))return accounts().stream().filter(a->a.username.equals(name)).findFirst().orElse(null);}}catch(Exception e){throw new IllegalStateException(e);}return null;}
 void telemetry(PatrolController.Telemetry t){try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO telemetry_history(device,task,battery,distance,temperature) VALUES(?,?,?,?,?)")){p.setString(1,t.device());p.setString(2,t.task());p.setDouble(3,t.battery());p.setDouble(4,t.distance());p.setDouble(5,t.temperature());p.executeUpdate();}catch(Exception e){throw new IllegalStateException(e);}}
 List<Map<String,Object>> history(String task){try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT * FROM telemetry_history WHERE task=? ORDER BY id DESC LIMIT 1000")){p.setString(1,task);List<Map<String,Object>> rows=new ArrayList<>();try(ResultSet r=p.executeQuery()){while(r.next())rows.add(Map.of("device",r.getString("device"),"battery",r.getDouble("battery"),"distance",r.getDouble("distance"),"temperature",r.getDouble("temperature"),"at",r.getTimestamp("recorded_at").toInstant().toString()));}return rows;}catch(Exception e){throw new IllegalStateException(e);}}
}
